# fmt: on

W = H = 64
ones = set(int(x) for x in indices_str.split())
grid = [[1 if (r * W + c + 1) in ones else 0 for c in range(W)] for r in range(H)]

# Save image
from PIL import Image

img = Image.new("RGB", (W, H), "black")
px = img.load()
for r in range(H):
    for c in range(W):
        if grid[r][c]:
            px[c, r] = (180, 255, 180)  # light green
img = img.resize((640, 640), Image.NEAREST)
img.save("out.png")

# Optional: print ASCII to quick-peek
for r in range(H):
    print("".join("█" if grid[r][c] else "░" for c in range(W)))

# Optional: try decoding rows as ASCII by grouping 8 bits
def bits_to_ascii(rows):
    s = []
    for r in rows:
        for i in range(0, 64, 8):
            byte = r[i : i + 8]
            val = int("".join(str(b) for b in byte), 2)
            if 32 <= val <= 126:
                s.append(chr(val))
            else:
                s.append(".")
        s.append("\n")
    return "".join(s)

print(bits_to_ascii(grid))
